'use client'

import { useEffect, useState } from 'react'
import { Input } from '@/components/ui/input'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Eye, EyeOff, Lock, Phone } from 'lucide-react'

export default function LoginPage() {
  const [phone, setPhone] = useState('')
  const [password, setPassword] = useState('')
  const [showPassword, setShowPassword] = useState(false)
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)

  const handleLogin = async (e) => {
    e.preventDefault()
    setError('')
    setLoading(true)

    try {
      const response = await fetch(
        'http://localhost:9000/accounts/api/v1/auth/login/',
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Accept: 'application/json',
          },
          body: JSON.stringify({ phone, password }),
        }
      )

      if (!response.ok) {
        if (response.status === 400) throw new Error('شماره موبایل یا رمز عبور نادرست است.')
        else if (response.status === 401) throw new Error('احراز هویت انجام نشد. دوباره تلاش کنید.')
        else throw new Error('مشکلی پیش آمده است.')
      }

      const data = await response.json()
      const { access, refresh } = data

      if (!access || !refresh) throw new Error('توکن‌های دسترسی بازگشتی ناقص‌اند.')

      // In real app, store tokens properly
      console.log('Login successful:', { access, refresh })
      alert('ورود موفقیت‌آمیز بود!')
    } catch (err) {
      setError(err.message || 'خطایی رخ داده است.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="relative min-h-screen overflow-hidden bg-gradient-to-br from-sky-50 via-blue-50 to-indigo-100" dir="rtl">
      {/* Background Animated Gradient Orbs */}
      <div className="absolute inset-0 overflow-hidden">
        <div className="absolute -left-40 top-0 h-96 w-96 animate-pulse rounded-full bg-gradient-to-br from-blue-400/30 to-cyan-300/20 blur-3xl" />
        <div className="absolute -right-40 top-20 h-[500px] w-[500px] animate-pulse rounded-full bg-gradient-to-br from-indigo-400/25 to-purple-300/15 blur-3xl" style={{ animationDelay: '1s' }} />
        <div className="absolute bottom-0 left-1/3 h-80 w-80 animate-pulse rounded-full bg-gradient-to-br from-sky-400/20 to-blue-300/15 blur-3xl" style={{ animationDelay: '2s' }} />
      </div>


      <div className="relative flex min-h-screen items-center justify-center px-4 py-12">
        <Card className="w-full max-w-md border border-white/50 bg-white/40 shadow-2xl backdrop-blur-2xl transition-all duration-300 hover:shadow-3xl">
          <CardHeader className="space-y-3 pb-4">
            {/* Logo with Animation */}
            <div className="flex justify-center">
            <div className="group relative">
                <div className="absolute -inset-3 rounded-[28px] bg-gradient-to-r from-sky-400/35 via-blue-400/30 to-indigo-400/35 blur-2xl transition-opacity duration-300 group-hover:opacity-90 opacity-70" />

                <div className="absolute -inset-1 rounded-[22px] bg-white/20 ring-1 ring-white/30 backdrop-blur-md transition-opacity duration-300 group-hover:opacity-60 opacity-40" />

                {/* logo container (keeps the “icon tile” look from the screenshot) */}
                <div className="relative flex h-16 w-16 items-center justify-center overflow-hidden rounded-2xl bg-gradient-to-br from-blue-500 to-indigo-600 shadow-[0_18px_40px_rgba(2,6,23,0.25)] ring-4 ring-white/50 transition-transform duration-300 group-hover:scale-[1.06] active:scale-[0.98]">
                {/* subtle top sheen */}
                <div className="pointer-events-none absolute inset-0 bg-gradient-to-b from-white/25 via-transparent to-transparent" />
                {/* tiny inner border */}
                <div className="pointer-events-none absolute inset-0 rounded-2xl ring-1 ring-white/35" />

                {/* ✅ put your website icon exactly here (same “place” on top of the tile) */}
                <img
                    src="/logo.svg" // or /logo.png
                    alt="Site logo"
                    className="relative h-9 w-9 object-contain drop-shadow-[0_6px_10px_rgba(0,0,0,0.25)]"
                    onError={(e) => {
                    ;(e.currentTarget as HTMLImageElement).style.display = 'none'
                    }}
                />

                {/* fallback if logo file not found */}
                <svg
                    className="relative h-9 w-9 text-white drop-shadow-[0_6px_10px_rgba(0,0,0,0.25)]"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                >
                    {/* <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"
                    /> */}
                </svg>
                </div>
            </div>
            </div>


            {/* Title */}
            <div className="text-center">
              <CardTitle className="bg-gradient-to-l from-slate-800 via-slate-900 to-slate-800 bg-clip-text text-3xl font-bold tracking-tight text-transparent">
                ورود به پنل مدیریت
              </CardTitle>
              <p className="mt-2 text-sm font-medium text-slate-600">
                با شماره موبایل و رمز عبور وارد شوید
              </p>
            </div>
          </CardHeader>

          <CardContent className="pt-2">
            <form onSubmit={handleLogin} className="space-y-5">
              {/* Phone Input */}
              <div className="space-y-2">
                <label htmlFor="phone" className="block text-sm font-semibold text-slate-700">
                  شماره موبایل
                </label>
                <div className="relative">
                  <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center pr-3">
                    <Phone className="h-5 w-5 text-slate-400" />
                  </div>
                  <Input
                    id="phone"
                    inputMode="tel"
                    autoComplete="tel"
                    value={phone}
                    onChange={(e) => setPhone(e.target.value)}
                    placeholder="09123456789"
                    className="h-12 border-white/60 bg-white/60 pr-10 text-right backdrop-blur-sm transition-all placeholder:text-slate-400 focus:border-blue-400 focus:bg-white/80 focus:ring-2 focus:ring-blue-400/20"
                    required
                  />
                </div>
              </div>

              {/* Password Input */}
              <div className="space-y-2">
                <label htmlFor="password" className="block text-sm font-semibold text-slate-700">
                  رمز عبور
                </label>
                <div className="relative">
                  <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center pr-3">
                    <Lock className="h-5 w-5 text-slate-400" />
                  </div>
                  <Input
                    id="password"
                    type={showPassword ? 'text' : 'password'}
                    autoComplete="current-password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder="رمز عبور خود را وارد کنید"
                    className="h-12 border-white/60 bg-white/60 px-10 text-right backdrop-blur-sm transition-all placeholder:text-slate-400 focus:border-blue-400 focus:bg-white/80 focus:ring-2 focus:ring-blue-400/20"
                    required
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute inset-y-0 left-0 flex items-center pl-3 text-slate-400 transition-colors hover:text-slate-600"
                  >
                    {showPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}
                  </button>
                </div>
              </div>

              {/* Forgot Password & Secure Login */}
              <div className="flex items-center justify-between pt-1 text-sm">
                <button
                  type="button"
                  className="font-medium text-blue-600 transition-colors hover:text-blue-700 hover:underline"
                >
                  رمز عبور را فراموش کرده‌اید؟
                </button>
                <div className="flex items-center gap-1 text-slate-600">
                  <svg className="h-4 w-4 text-green-500" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M2.166 4.999A11.954 11.954 0 0010 1.944 11.954 11.954 0 0017.834 5c.11.65.166 1.32.166 2.001 0 5.225-3.34 9.67-8 11.317C5.34 16.67 2 12.225 2 7c0-.682.057-1.35.166-2.001zm11.541 3.708a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
                  </svg>
                  <span className="font-medium">ورود امن</span>
                </div>
              </div>

              {/* Error Message */}
              {error && (
                <div className="animate-shake rounded-xl border border-red-300/60 bg-red-50/80 px-4 py-3 text-sm font-medium text-red-700 backdrop-blur-sm">
                  {error}
                </div>
              )}

              {/* Submit Button */}
              <Button
                type="submit"
                disabled={loading}
                className="h-12 w-full rounded-xl bg-gradient-to-l from-blue-600 to-indigo-600 font-semibold text-white shadow-lg transition-all hover:from-blue-700 hover:to-indigo-700 hover:shadow-xl disabled:opacity-60"
              >
                {loading ? (
                  <span className="flex items-center gap-2">
                    <svg className="h-5 w-5 animate-spin" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none" />
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
                    </svg>
                    در حال ورود...
                  </span>
                ) : (
                  'ورود'
                )}
              </Button>

              {/* Terms */}
              <p className="pt-2 text-center text-xs text-slate-600">
                با ورود، شما{' '}
                <button type="button" className="font-medium text-blue-600 hover:underline">
                  قوانین و شرایط استفاده
                </button>{' '}
                را می‌پذیرید.
              </p>
            </form>
          </CardContent>
        </Card>
      </div>

      <style jsx>{`
        @keyframes float {
          0%, 100% { transform: translateY(0) rotate(0deg); }
          50% { transform: translateY(-20px) rotate(5deg); }
        }
        
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          10%, 30%, 50%, 70%, 90% { transform: translateX(-5px); }
          20%, 40%, 60%, 80% { transform: translateX(5px); }
        }
        
        .animate-float {
          animation: float 6s ease-in-out infinite;
        }
        
        .animate-shake {
          animation: shake 0.5s ease-in-out;
        }
      `}</style>
    </div>
  )
}